#!/usr/bin/env bash
set -Eeuo pipefail

# OMNILINK self-contained installer 2.3.0
# AJF Tech Malang

if [[ "${OMNILINK_SELF_REEXEC:-0}" != "1" && ! -t 0 ]]; then
  _tmp="$(mktemp /tmp/omnilink-installer.XXXXXX.sh)"
  cat >"$_tmp"
  chmod 700 "$_tmp"
  OMNILINK_SELF_REEXEC=1 bash "$_tmp" "$@"
  _rc=$?
  rm -f "$_tmp"
  exit $_rc
fi

APP_VERSION="2.3.0"
INSTALL_ROOT="${OMNILINK_ROOT:-/opt/omnilink}"
SERVICE_USER="${OMNILINK_USER:-omnilink}"
PORT="${OMNILINK_PORT:-18787}"
HTTPS_PORT="${OMNILINK_HTTPS_PORT:-18788}"
PUBLIC_HOST="${OMNILINK_PUBLIC_HOST:-}"
TS3_VERSION="3.1.10"
TS3_CLIENT_NAME="TeamSpeak3-Client-linux_amd64-3.1.10.run"
TS3_CLIENT_SHA256="63f3781c1f49ccc26368d9238a3e2aeca0e57dcb65a1c4022341ad7e8ba4fe9d"
TS3_CLIENT_URL="${OMNILINK_TS3_CLIENT_URL:-https://downloads.sourceforge.net/project/hgmnetwork-v5-ts3-client/TS3-Client-v3.1.10/TeamSpeak3-Client-linux_amd64-3.1.10.run}"
TS3_CLIENT_FILE="${OMNILINK_TS3_CLIENT_FILE:-}"
NO_SERVICE="${OMNILINK_NO_SERVICE:-0}"
FORCE="${OMNILINK_FORCE:-0}"
ENV_DIR="${OMNILINK_ENV_DIR:-/etc/omnilink}"
SERVICE_FILE="/etc/systemd/system/omnilink.service"

if [[ -z "${OMNILINK_ADMIN_TOKEN:-}" ]]; then
  OMNILINK_ADMIN_TOKEN="$(printf '\061\062\063\064\065\066')"
fi

log(){ printf '[OMNILINK] %s\n' "$*"; }
die(){ printf '[OMNILINK] ERROR: %s\n' "$*" >&2; exit 1; }

if [[ "$(uname -m)" != "x86_64" ]]; then
  die 'TeamSpeak Client 3.1.10 yang digunakan installer ini membutuhkan x86_64/amd64'
fi

if [[ "$NO_SERVICE" != "1" && "${EUID:-$(id -u)}" != "0" ]]; then
  die 'jalankan sebagai root, contoh: curl -fsSL <URL>/install.sh | sudo bash'
fi

case "$(uname -m)" in
  x86_64|amd64|aarch64|arm64) ;;
  *) die "arsitektur tidak didukung: $(uname -m)" ;;
esac
node_ok=0
if command -v node >/dev/null 2>&1; then
  major="$(node -p 'process.versions.node.split(".")[0]')"
  [[ "$major" -ge 20 ]] && node_ok=1
fi

if [[ "$node_ok" != "1" && "$NO_SERVICE" != "1" ]]; then
  if command -v apt-get >/dev/null 2>&1; then
    log 'Installing Node.js 22 prerequisite...'
    apt-get update
    apt-get install -y ca-certificates curl openssl tar
    curl -fsSL https://deb.nodesource.com/setup_22.x | bash -
    apt-get install -y nodejs
  elif command -v dnf >/dev/null 2>&1; then
    log 'Installing Node.js 22 prerequisite...'
    dnf install -y ca-certificates curl openssl tar
    curl -fsSL https://rpm.nodesource.com/setup_22.x | bash -
    dnf install -y nodejs
  elif command -v yum >/dev/null 2>&1; then
    log 'Installing Node.js 22 prerequisite...'
    yum install -y ca-certificates curl openssl tar
    curl -fsSL https://rpm.nodesource.com/setup_22.x | bash -
    yum install -y nodejs
  else
    die 'Node.js >=20 tidak ditemukan dan package manager apt/dnf/yum tidak tersedia'
  fi
fi

command -v node >/dev/null 2>&1 || die 'node tidak ditemukan'
node_major="$(node -p 'process.versions.node.split(".")[0]')"
[[ "$node_major" -ge 20 ]] || die "Node.js >=20 diperlukan; terdeteksi $(node -v)"
if [[ -e "$INSTALL_ROOT/.omnilink-installed" && "$FORCE" != "1" ]]; then
  die "$INSTALL_ROOT sudah merupakan instalasi OmniLink. Gunakan OMNILINK_FORCE=1 untuk reinstall yang disengaja."
fi

TMP_DIR="$(mktemp -d /tmp/omnilink-release.XXXXXX)"
cleanup(){ rm -rf "$TMP_DIR"; }
trap cleanup EXIT
mkdir -p "$TMP_DIR/payload"

awk '/^__OMNILINK_TS_BRIDGE__$/ {exit} /^__OMNILINK_PAYLOAD__$/ {f=1; next} f {print}' "$0" | base64 -d > "$TMP_DIR/release.tgz"
tar -xzf "$TMP_DIR/release.tgz" -C "$TMP_DIR/payload"
[[ -f "$TMP_DIR/payload/VERSION" ]] || die 'payload OmniLink tidak valid'
mkdir -p "$TMP_DIR/bridge"
awk 'f{print} /^__OMNILINK_TS_BRIDGE__$/ {f=1; next}' "$0" | base64 -d > "$TMP_DIR/bridge.tgz"
tar -xzf "$TMP_DIR/bridge.tgz" -C "$TMP_DIR/bridge"
[[ -f "$TMP_DIR/bridge/index.js" && -f "$TMP_DIR/bridge/run-client.sh" ]] || die 'payload TeamSpeak bridge tidak valid'

prepare_ts3(){
  local src=""
  if [[ -n "$TS3_CLIENT_FILE" ]]; then
    [[ -f "$TS3_CLIENT_FILE" ]] || die "TeamSpeak 3.1.10 file tidak ditemukan: $TS3_CLIENT_FILE"
    src="$TS3_CLIENT_FILE"
  else
    log "Downloading TeamSpeak Client $TS3_VERSION..."
    curl -fL --retry 3 --connect-timeout 10 --max-time 180 "$TS3_CLIENT_URL" -o "$TMP_DIR/$TS3_CLIENT_NAME" || die "TeamSpeak 3.1.10 tidak tersedia dari URL yang dikonfigurasi. Set OMNILINK_TS3_CLIENT_URL atau OMNILINK_TS3_CLIENT_FILE ke paket TeamSpeak 3.1.10 yang Anda berhak gunakan."
    src="$TMP_DIR/$TS3_CLIENT_NAME"
  fi
  echo "$TS3_CLIENT_SHA256  $src" | sha256sum -c - >/dev/null || die "SHA-256 TeamSpeak 3.1.10 tidak cocok"
  mkdir -p "$TMP_DIR/ts3"
  printf '\nq\ny\n\n' | sh "$src" --target "$TMP_DIR/ts3/client" >/tmp/omnilink-ts3-install.log 2>&1 || { tail -80 /tmp/omnilink-ts3-install.log >&2; die 'Gagal mengekstrak TeamSpeak 3.1.10'; }
  [[ -x "$TMP_DIR/ts3/client/ts3client_linux_amd64" ]] || die 'TeamSpeak 3.1.10 binary tidak ditemukan setelah ekstraksi'
}

install_ts_deps(){
  command -v apt-get >/dev/null 2>&1 || die 'TeamSpeak 3.1.10 headless installer saat ini memerlukan Debian/Ubuntu (apt-get)'
  apt-get update
  apt-get install -y xvfb pulseaudio xdotool libnss3 libnspr4 libxcomposite1 libxdamage1 libxcursor1 libxrandr2 libxslt1.1 liblcms2-2 libatomic1 libxcb-icccm4 libxcb-image0 libxcb-keysyms1 libxcb-render-util0 libxcb-shape0 libxcb-xinerama0 libxcb-xkb1 libxkbcommon-x11-0 libgl1-mesa-dri libglx-mesa0 libegl1 x11-utils mesa-utils
}

prepare_ts3
if [[ "$NO_SERVICE" != "1" ]]; then
  install_ts_deps
fi

if [[ -d "$INSTALL_ROOT" && "$FORCE" == "1" && "$NO_SERVICE" != "1" ]]; then
  systemctl disable --now omnilink-teamspeak-watchdog.service 2>/dev/null || true
  systemctl disable --now omnilink-teamspeak-bridge.service 2>/dev/null || true
  systemctl disable --now omnilink-teamspeak-client.service 2>/dev/null || true
  systemctl stop omnilink.service 2>/dev/null || true
fi

mkdir -p "$INSTALL_ROOT"
cp -a "$TMP_DIR/payload/." "$INSTALL_ROOT/"
mkdir -p "$INSTALL_ROOT/data" "$INSTALL_ROOT/bridges/teamspeak" "$INSTALL_ROOT/logs"

if ! id -u "$SERVICE_USER" >/dev/null 2>&1; then
  useradd --system --home-dir "$INSTALL_ROOT" --shell /usr/sbin/nologin "$SERVICE_USER"
fi
TS_HOME="/var/lib/omnilink-ts"
if ! id -u omnilink-ts >/dev/null 2>&1; then
  useradd --system --home-dir "$TS_HOME" --shell /usr/sbin/nologin omnilink-ts
else
  usermod -d "$TS_HOME" omnilink-ts >/dev/null 2>&1 || true
fi
mkdir -p "$TS_HOME/.ts3client"
chown -R omnilink-ts:omnilink-ts "$TS_HOME"
chmod 700 "$TS_HOME" "$TS_HOME/.ts3client"
usermod -a -G "$SERVICE_USER" omnilink-ts >/dev/null 2>&1 || true

TS3_INSTALL_ROOT="/opt/teamspeak3-client-3.1.10"
rm -rf "$TS3_INSTALL_ROOT"
mkdir -p "$TS3_INSTALL_ROOT"
cp -a "$TMP_DIR/ts3/client/." "$TS3_INSTALL_ROOT/"
ln -sfn "$TS3_INSTALL_ROOT" /opt/teamspeak3-client-current

cp -a "$TMP_DIR/bridge/." "$INSTALL_ROOT/bridges/teamspeak/"
if [[ -f "$TMP_DIR/bridge/settings-template.db" ]]; then
  cp -f "$TMP_DIR/bridge/settings-template.db" "$TS_HOME/.ts3client/settings.db"
fi
chmod 755 "$INSTALL_ROOT/bridges/teamspeak/run-client.sh"
cd "$INSTALL_ROOT/bridges/teamspeak"
npm ci --omit=dev >/tmp/omnilink-ts-npm.log 2>&1 || { tail -80 /tmp/omnilink-ts-npm.log >&2; die 'Gagal memasang dependency TeamSpeak bridge'; }

TS_API_KEY="$(openssl rand -hex 24)"
mkdir -p "$INSTALL_ROOT/.ts3client" "$INSTALL_ROOT/config" "$INSTALL_ROOT/cache"
cat > "$TS_HOME/.ts3client/clientquery.ini" <<EOF
[General]
api_key=$TS_API_KEY
logging_enabled=false
open_remote=false
EOF
ln -sfn "$TS_HOME/.ts3client/clientquery.ini" "$INSTALL_ROOT/.ts3client/clientquery.ini"
chown -R omnilink-ts:"$SERVICE_USER" "$TS_HOME/.ts3client"

TS_SERVER_HOST="${OMNILINK_TS_SERVER_HOST:-ts3.my.id}"
TS_VOICE_PORT="${OMNILINK_TS_VOICE_PORT:-9987}"
TS_QUERY_PORT="${OMNILINK_TS_QUERY_PORT:-10011}"
TS_NICKNAME="${OMNILINK_TS_NICKNAME:-Universal OMNILINK Bridge}"
TS_CHANNEL_NAME="${OMNILINK_TS_CHANNEL_NAME:-omni test}"
TS_CHANNEL_ID="${OMNILINK_TS_CHANNEL_ID:-3833}"
TS_SERVER_PASSWORD="${OMNILINK_TS_SERVER_PASSWORD:-}"
TS_CHANNEL_PASSWORD="${OMNILINK_TS_CHANNEL_PASSWORD:-}"
TS_CALLSIGN="${OMNILINK_TS_CALLSIGN:-TEST1}"

cat > "$INSTALL_ROOT/data/teamspeak.json" <<EOF
{
  "enabled": true,
  "serverHost": "$TS_SERVER_HOST",
  "voicePort": $TS_VOICE_PORT,
  "queryPort": $TS_QUERY_PORT,
  "fileTransferPort": 30033,
  "serverPassword": "$TS_SERVER_PASSWORD",
  "nickname": "$TS_NICKNAME",
  "channelName": "$TS_CHANNEL_NAME",
  "channelPassword": "$TS_CHANNEL_PASSWORD",
  "channelId": $TS_CHANNEL_ID,
  "omnilinkRoomId": "11",
  "omnilinkRoomName": "teamspeak",
  "omnilinkCallsign": "$TS_CALLSIGN",
  "pcmRxPort": 19101,
  "pcmTxPort": 19102,
  "bridgeHealthPort": 18891,
  "joinPort": 19103,
  "autoReconnect": true,
  "reconnectDelaySec": 5,
  "connectRequested": true
}
EOF

node - "$INSTALL_ROOT/data/state.json" "$OMNILINK_ADMIN_TOKEN" <<'NODE'
const fs=require("fs"), crypto=require("crypto");
const file=process.argv[2], adminToken=process.argv[3];
let s={users:[],rooms:[],gateways:[],bridges:[],activeTalk:{},audit:[],dtmfConfig:{}};
try{s=JSON.parse(fs.readFileSync(file,"utf8"));}catch{}
s.users ||= []; s.rooms ||= []; s.gateways ||= []; s.bridges ||= []; s.activeTalk ||= {}; s.audit ||= []; s.dtmfConfig ||= {};
let admin=s.users.find(u=>String(u.callsign||"").toUpperCase()==="ADMIN");
if(!admin){
  admin={id:"admin",callsign:"ADMIN",kind:"user",level:4,enabled:true,token:adminToken,mustChangePassword:true,gps:true,channels:[]};
  s.users.push(admin);
}else{
  admin.token=adminToken;
  admin.mustChangePassword=true;
  admin.level=4;
  admin.enabled=true;
}
if(!s.users.some(u=>String(u.callsign||"").toUpperCase()==="TEST1")){
  s.users.push({id:"bridge-test1",callsign:"TEST1",kind:"user",level:1,enabled:true,token:crypto.randomBytes(24).toString("hex"),gps:false,channels:[]});
}
if(!s.rooms.some(r=>String(r.id)==="11")){
  s.rooms.push({id:"11",name:"teamspeak",description:"TeamSpeak 3 Bridge",enabled:true,createdAt:new Date().toISOString()});
}
fs.writeFileSync(file,JSON.stringify(s,null,2)+"\n");
NODE

chown -R "$SERVICE_USER:$SERVICE_USER" "$INSTALL_ROOT/bridges/teamspeak"
chown -R omnilink-ts:"$SERVICE_USER" "$INSTALL_ROOT/logs"
chown -R omnilink-ts:"$SERVICE_USER" "$INSTALL_ROOT/.ts3client" "$INSTALL_ROOT/config" "$INSTALL_ROOT/cache"
chown root:"$SERVICE_USER" "$INSTALL_ROOT/data"
chown root:"$SERVICE_USER" "$INSTALL_ROOT/data/state.json" "$INSTALL_ROOT/data/teamspeak.json"
chmod 770 "$INSTALL_ROOT/data"
chmod 750 "$INSTALL_ROOT/bridges/teamspeak"
chmod 640 "$INSTALL_ROOT/data/state.json" "$INSTALL_ROOT/data/teamspeak.json" "$INSTALL_ROOT/.ts3client/clientquery.ini"
chmod 700 "$INSTALL_ROOT/.ts3client"

printf '%s\n' "$APP_VERSION" > "$INSTALL_ROOT/.omnilink-installed"

cat > "$TMP_DIR/omnilink.env" <<EOF
HOST=0.0.0.0
PORT=$PORT
HTTPS_PORT=$HTTPS_PORT
OMNILINK_HOME=$INSTALL_ROOT
OMNILINK_DATA_DIR=$INSTALL_ROOT/data
OMNILINK_DB=$INSTALL_ROOT/data/state.json
OMNILINK_WEB_DIR=$INSTALL_ROOT/clients/web
OMNILINK_ADMIN_DIR=$INSTALL_ROOT/server/admin
OMNILINK_ADMIN_TOKEN=$OMNILINK_ADMIN_TOKEN
OMNILINK_SMART_PORT_DETECT=false
EOF

if [[ "$NO_SERVICE" == "1" ]]; then
  cp "$TMP_DIR/omnilink.env" "$INSTALL_ROOT/omnilink.env"
  chmod 600 "$INSTALL_ROOT/omnilink.env"
  log "Test install complete: $INSTALL_ROOT"
  log "Node: $(node -v)"
  printf '%s\n' "ADMIN_PASSWORD_DEFAULT=$(printf '\061\062\063\064\065\066')"
  exit 0
fi
cat > "$SERVICE_FILE" <<EOF
[Unit]
Description=OMNILINK Self-Hosted Communication Server
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=root
WorkingDirectory=$INSTALL_ROOT
EnvironmentFile=$ENV_DIR/omnilink.env
ExecStart=/usr/bin/env node $INSTALL_ROOT/server/src/index.js
Restart=always
RestartSec=3
LimitNOFILE=65536
NoNewPrivileges=true
PrivateTmp=true
ProtectHome=true
ProtectSystem=strict
ReadWritePaths=$INSTALL_ROOT/data

[Install]
WantedBy=multi-user.target
EOF

TS_CLIENT_SERVICE="/etc/systemd/system/omnilink-teamspeak-client.service"
TS_BRIDGE_SERVICE="/etc/systemd/system/omnilink-teamspeak-bridge.service"
TS_WATCHDOG_SERVICE="/etc/systemd/system/omnilink-teamspeak-watchdog.service"

cat > "$TS_CLIENT_SERVICE" <<EOF
[Unit]
Description=OMNILINK TeamSpeak Client 3.1.10
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=omnilink-ts
Group=omnilink-ts
SupplementaryGroups=$SERVICE_USER
WorkingDirectory=$INSTALL_ROOT
Environment=OMNILINK_HOME=$INSTALL_ROOT
Environment=HOME=$TS_HOME
Environment=XDG_CONFIG_HOME=$INSTALL_ROOT/config
Environment=XDG_CACHE_HOME=$INSTALL_ROOT/cache
Environment=XDG_RUNTIME_DIR=/run/omnilink-ts
RuntimeDirectory=omnilink-ts
RuntimeDirectoryMode=0700
ExecStart=$INSTALL_ROOT/bridges/teamspeak/run-client.sh
Restart=always
RestartSec=3
LimitNOFILE=65536

[Install]
WantedBy=multi-user.target
EOF

cat > "$TS_BRIDGE_SERVICE" <<EOF
[Unit]
Description=OMNILINK TeamSpeak Bridge
Requires=omnilink.service
After=omnilink.service omnilink-teamspeak-client.service network-online.target
Wants=network-online.target

[Service]
Type=simple
User=$SERVICE_USER
Group=$SERVICE_USER
WorkingDirectory=$INSTALL_ROOT/bridges/teamspeak
Environment=OMNILINK_HOME=$INSTALL_ROOT
Environment=OMNILINK_URL=ws://127.0.0.1:$PORT/ws
Environment=HOME=$INSTALL_ROOT
ExecStart=/usr/bin/env node $INSTALL_ROOT/bridges/teamspeak/index.js
Restart=always
RestartSec=3
LimitNOFILE=65536

[Install]
WantedBy=multi-user.target
EOF

cat > "$TS_WATCHDOG_SERVICE" <<EOF
[Unit]
Description=OMNILINK TeamSpeak Client Watchdog
Requires=omnilink-teamspeak-client.service
After=omnilink-teamspeak-client.service

[Service]
Type=simple
User=root
Group=root
Environment=OMNILINK_HOME=$INSTALL_ROOT
ExecStart=/usr/bin/python3 $INSTALL_ROOT/bridges/teamspeak/ts-watchdog.py
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

mkdir -p "$ENV_DIR"
install -m 600 "$TMP_DIR/omnilink.env" "$ENV_DIR/omnilink.env"
systemctl daemon-reload
systemctl enable --now omnilink.service
systemctl enable omnilink-teamspeak-client.service omnilink-teamspeak-bridge.service omnilink-teamspeak-watchdog.service
systemctl start omnilink-teamspeak-client.service
ok=0
for _ in $(seq 1 30); do
  if ss -lnt 2>/dev/null | grep -q ":25639 "; then
    ok=1
    break
  fi
  sleep 1
done
if [[ "$ok" != "1" ]]; then
  systemctl --no-pager --full status omnilink-teamspeak-client.service || true
  tail -100 "$INSTALL_ROOT/logs/ts-client.log" 2>/dev/null || true
  die 'TeamSpeak Client 3.1.10 gagal menyediakan ClientQuery :25639'
fi
systemctl start omnilink-teamspeak-bridge.service omnilink-teamspeak-watchdog.service

for _ in $(seq 1 15); do
  if curl -fsS --max-time 2 "http://127.0.0.1:$PORT/health" >/dev/null 2>&1; then
    ok=1
    break
  fi
  sleep 1
done

if [[ "$ok" != "1" ]]; then
  systemctl --no-pager --full status omnilink.service || true
  die 'OmniLink gagal melewati health check'
fi

log "OMNILINK $APP_VERSION installed and healthy."
if [[ -z "$PUBLIC_HOST" ]]; then
  PUBLIC_HOST="$(curl -4 -fsS --max-time 5 https://api.ipify.org 2>/dev/null || true)"
fi
[[ -n "$PUBLIC_HOST" ]] || PUBLIC_HOST="SERVER_IP"
log "Web Client: http://$PUBLIC_HOST:$PORT/"
log "Admin Web: http://$PUBLIC_HOST:$PORT/admin/"
log "Server Address (Android/PC): $PUBLIC_HOST:$PORT"
log "Health Check: http://$PUBLIC_HOST:$PORT/health"
if [[ "$HTTPS_PORT" != "0" ]]; then
  log "HTTPS URL (when TLS is configured): https://$PUBLIC_HOST:$HTTPS_PORT/"
fi
log "Admin username: ADMIN"
log "Initial admin password: $(printf '\061\062\063\064\065\066') (must be changed on first login)"
log "TeamSpeak Client: 3.1.10"
log "TeamSpeak Server: $TS_SERVER_HOST:$TS_VOICE_PORT"
log "ClientQuery: 127.0.0.1:25639 (verified)"
log "TeamSpeak Bridge Health: http://127.0.0.1:18891/health"
log "Service: systemctl status omnilink"
log "TeamSpeak services: omnilink-teamspeak-client.service / omnilink-teamspeak-bridge.service / omnilink-teamspeak-watchdog.service"
exit 0

__OMNILINK_PAYLOAD__


__OMNILINK_TS_BRIDGE__

